"""Multi-priority task queue."""
import heapq
from dataclasses import dataclass, field
from typing import Any


@dataclass(order=True)
class Task:
    priority: int
    seq: int = field(compare=True)
    payload: Any = field(compare=False)


class TaskQueue:
    """Priority queue where lower priority number = higher urgency."""

    def __init__(self):
        self._heap = []
        self._seq = 0  # tie-breaker

    def enqueue(self, payload: Any, priority: int = 10) -> None:
        """Add a task with given priority (lower = more urgent)."""
        raise NotImplementedError

    def dequeue(self) -> Any:
        """Remove and return the highest-priority task payload. Raise IndexError if empty."""
        raise NotImplementedError

    def peek(self) -> Any:
        """Return highest-priority payload without removing. Raise IndexError if empty."""
        raise NotImplementedError

    def size(self) -> int:
        """Return number of tasks in the queue."""
        raise NotImplementedError

    def clear(self) -> None:
        """Remove all tasks."""
        raise NotImplementedError
